App.register({group:'assets',label:'数字资产',icon:'▧',routes:[{path:'assets/library',title:'资产中心',icon:'▧',permission:'assets',render(){
 const p=App.project();if(!p)return UI.page('DIGITAL ASSET / LIBRARY','尚未选择项目','选择项目后查看该项目的数字资产与版本关系。','',`<div class="card">${UI.empty('没有可用项目','当前身份没有可访问的项目。')}</div>`);
 const list=DB.assets.filter(a=>a.tenant===p.tenant&&a.project===p.title);
 const count=type=>list.filter(a=>a.type===type).length;
 return UI.page('DIGITAL ASSET / LIBRARY','数字资产中心','当前项目：'+UI.esc(p.title)+' · 统一管理剧本、人物、场景、分镜、视频、音频与成片资产。',UI.btn('查看项目档案','go:workspace/detail','btn'),`
 <div class="grid grid-4">${UI.metric('当前项目资产',list.length,'仅展示所选项目资产','▧')}${UI.metric('人物 / 场景',count('人物设定')+' / '+count('场景设定'),'可追溯视觉身份档案','♙')}${UI.metric('分镜 / 音频',count('分镜')+' / '+count('音频'),'关联镜头生产单元','♫')}${UI.metric('正式成片',count('成片'),'当前项目归档资产','▶')}</div>
 <div class="card section-gap"><div class="toolbar"><div class="toolbar-left"><b class="small">资产目录 · ${UI.esc(p.title)}</b><span class="tiny muted mono">${UI.esc(p.id)}</span></div><input class="search" data-filter placeholder="搜索资产名称 / 编号"></div>
 ${UI.table(['资产名称','类型','来源项目','版本','创建者','更新时间','归属'],list.map(a=>`<tr data-search="${UI.esc(a.name)} ${UI.esc(a.id)}"><td><div class="entity"><div class="entity-mark">${UI.esc(a.type.slice(0,1))}</div><div><div class="entity-name">${UI.esc(a.name)}</div><div class="entity-meta mono">${UI.esc(a.id)}</div></div></div></td><td>${UI.esc(a.type)}</td><td>${UI.esc(a.project)}</td><td class="mono">${UI.esc(a.version)}</td><td>${UI.esc(a.owner)}</td><td>${UI.esc(a.date)}</td><td>${UI.tag('当前项目','green')}</td></tr>`))}
 </div>${list.length?'':`<div class="card section-gap">${UI.empty('当前项目暂无资产','进入 AI 创作与生产流程后，相关资产会关联到该项目。')}</div>`}<div class="notice section-gap">资产复用遵循租户边界。跨租户引用需要明确授权，不因企业级汇总权限自动获得素材读取或修改权。</div>`);
}}]});